2	import * as THREE from "three";
3	
4	const WALK_SPEED = 1.2; // metres per second
5	const TURN_RATE = 3; // how quickly the view turns towards where it's heading
6	const LINE_RADIUS = 0.02; // faint guide line under the arrows
7	const LINE_LIFT = 0.03; // metres above the floor, so the line doesn't sink into it
8	const COLOR = 0x22d3ee;
9	// Chevron arrows along the route, flowing towards the target.
10	const ARROW_SPACING = 0.45; // metres between arrows
11	const ARROW_SPEED = 0.7; // metres per second the arrows flow
12	const ARROW_GROW = 0.3; // arrows grow in and shrink out over this distance at the ends
13	const END_GAP = 0.3; // no arrows this close to the end ring
14	const MAX_ARROWS = 400;
