16	// A flat ">" lying on the floor, pointing along +z, about 22 x 26 cm.
17	function chevronGeometry() {
18	  const shape = new THREE.Shape();
19	  const outline = [
20	    [0, 0.11],
21	    [0.13, -0.02],
22	    [0.13, -0.1],
23	    [0, 0.03],
24	    [-0.13, -0.1],
25	    [-0.13, -0.02],
26	  ];
27	  shape.moveTo(...outline[0]);
28	  for (const point of outline.slice(1)) shape.lineTo(...point);
29	  shape.closePath();
30	  const geometry = new THREE.ShapeGeometry(shape);
31	  geometry.rotateX(Math.PI / 2); // tip from +y to +z, so it lies flat on the floor
32	  return geometry;
33	}
34	const LIVE_STEP = 0.1; // metres moved before the route is re-planned or trimmed
35	const LIVE_WAIT = 50; // milliseconds between live re-plans, so requests don't pile up
