37	async function callApi(path, body) {
38	  const response = await fetch(path, {
39	    method: "POST",
40	    headers: { "Content-Type": "application/json" },
41	    body: JSON.stringify(body ?? {}),
42	  });
43	  const data = await response.json().catch(() => ({}));
44	  if (!response.ok) {
45	    const detail = typeof data.detail === "string" ? data.detail : `Backend error ${response.status}`;
46	    throw new Error(detail);
47	  }
48	  return data;
49	}
