51	// Keep the path up to the viewing point, which lies on it.
52	function pathToViewPoint(path, viewFrom) {
53	  const points = path.map((p) => new THREE.Vector3(...p));
54	  const view = new THREE.Vector3(...viewFrom);
55	  let best = { distance: Infinity, index: 0 };
56	  const line = new THREE.Line3();
57	  const near = new THREE.Vector3();
58	  for (let i = 0; i + 1 < points.length; i++) {
59	    line.set(points[i], points[i + 1]);
60	    line.closestPointToPoint(view, true, near);
61	    const distance = near.distanceTo(view);
62	    if (distance < best.distance) best = { distance, index: i };
63	  }
64	  return [...points.slice(0, best.index + 1), view];
65	}
