136	  // Place the arrows for this frame: evenly spaced, flowing towards the end, growing in and out.
137	  // They're spaced by distance to the end, not from the start, so live re-plans and the trimming
138	  // while walking (which both redraw the route from a new start) don't make them jump.
139	  function animate(dt) {
140	    if (!track) return;
141	    clock += dt;
142	    phase = (phase + ARROW_SPEED * dt) % ARROW_SPACING;
143	    if (ring) ring.scale.setScalar(1 + 0.15 * Math.sin(clock * 4));
144	    const stop = track.total - END_GAP;
145	    const nearest = END_GAP + ARROW_SPACING - phase; // distance to the end of the closest arrow
146	    const n = Math.min(Math.floor((track.total - nearest) / ARROW_SPACING), MAX_ARROWS - 1);
147	    let segment = 0;
148	    let count = 0;
149	    // From the farthest arrow to the nearest, so the distance from the start only grows.
150	    for (let k = n; k >= 0; k--) {
151	      const d = track.total - (nearest + k * ARROW_SPACING);
152	      if (d < 0) continue;
153	      while (segment < track.lengths.length - 2 && track.lengths[segment + 1] < d) segment++;
154	      const a = track.points[segment];
155	      const b = track.points[segment + 1];
156	      const span = track.lengths[segment + 1] - track.lengths[segment];
157	      dummy.position.lerpVectors(a, b, span > 0 ? (d - track.lengths[segment]) / span : 0);
158	      dummy.rotation.set(0, Math.atan2(b.x - a.x, b.z - a.z), 0);
159	      const grow = Math.min(1, d / ARROW_GROW, (stop - d) / ARROW_GROW);
