"""Drive the real viewer with real pointer events, and check routes against where the chair stands."""
import json

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:8223"
CHAIR = "obj-0021"
FLOOR = 1.167
EYE = 1.6

HELPERS = r"""
(() => {
  const v = window.plantViewer;
  const byId = (id) => v.objects.find((o) => o.asset.object_id === id);
  const root = v.objects[0].box.parent;
  const V = v.objects[0].center.constructor;
  const FLOOR = %(floor)s;
  function screen(x, z) {
    const w = root.localToWorld(new V(x, FLOOR, z));
    v.camera.updateMatrixWorld();
    w.project(v.camera);
    return [((w.x + 1) / 2) * innerWidth, ((1 - w.y) / 2) * innerHeight];
  }
  function footprint(o) {
    const a = o.asset;
    const hx = Math.abs(a.bbox_max[0] - a.bbox_min[0]) / 2;
    const hz = Math.abs(a.bbox_max[2] - a.bbox_min[2]) / 2;
    return [o.center.x - hx, o.center.z - hz, o.center.x + hx, o.center.z + hz];
  }
  function gap(path, box) {
    let best = Infinity;
    for (let i = 0; i + 1 < path.length; i++) {
      for (let s = 0; s <= 1.0001; s += 0.01) {
        const x = path[i][0] + (path[i + 1][0] - path[i][0]) * s;
        const z = path[i][2] + (path[i + 1][2] - path[i][2]) * s;
        const dx = Math.max(box[0] - x, 0, x - box[2]);
        const dz = Math.max(box[1] - z, 0, z - box[3]);
        best = Math.min(best, Math.hypot(dx, dz));
      }
    }
    return best;
  }
  function moveViewer(x, z) {
    const w = root.localToWorld(new V(x, FLOOR, z));
    v.camera.position.set(w.x, v.camera.position.y, w.z);
  }
  function look(pitch, yaw = 0) {
    v.camera.rotation.set(pitch, yaw, 0, "YXZ");
  }
  window.__h = { v, byId, root, V, screen, footprint, gap, moveViewer, look };
})();
""" % {"floor": FLOOR}

STATE = """async (id) => {
  const h = window.__h, v = h.v, o = h.byId(id);
  let backend = null, status = null;
  try {
    const r = await fetch('/api/assets/' + encodeURIComponent(id));
    status = r.status;
    if (r.ok) backend = (await r.json()).center;
  } catch (e) { status = String(e); }
  const route = v.route.state.route;
  const box = h.footprint(o);
  return {
    viewer: o.center.toArray(),
    backend,
    backendStatus: status,
    gap: route ? h.gap(route.path, box) : null,
    length: route ? route.length : null,
    path: route ? route.path.map((p) => [+p[0].toFixed(2), +p[2].toFixed(2)]) : null,
    changes: v.objectLayer.state.changes.length,
    posted: v.route.state.posted,
    status: document.getElementById('status').textContent,
    start: v.route.state.start ? [+v.route.state.start.x.toFixed(2), +v.route.state.start.z.toFixed(2)] : null,
    walking: !!v.route.state.walking,
  };
}"""


class Run:
    def __init__(self, playwright, view="objects", width=1024, height=700):
        self.browser = playwright.chromium.launch(
            executable_path="/snap/bin/chromium",
            headless=True,
            args=["--no-sandbox", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"],
        )
        self.page = self.browser.new_context(viewport={"width": width, "height": height}).new_page()
        self.view = view
        self.errors = []
        self.saves = []  # every POST /api/changes
        self.checks = []
        self.page.on("pageerror", lambda e: self.errors.append(str(e)[:200]))
        self.page.on("response", self._on_response)
        self.load()

    def _on_response(self, response):
        url = response.url
        if url.endswith("/api/changes") and response.request.method == "POST":
            body = json.loads(response.request.post_data or "{}")
            try:
                detail = response.json().get("detail") if not response.ok else ""
            except Exception:
                detail = "?"
            self.saves.append((body.get("object_id"), [round(v, 3) for v in body.get("position") or []], response.status, detail))
        elif "/check-move" in url:
            timing = response.request.timing
            self.checks.append(timing["responseEnd"] - timing["requestStart"])

    def load(self):
        page = self.page
        extra = f"&view={self.view}" if self.view else ""
        page.goto(f"{BASE}/?lod=0&res=0.15{extra}")
        page.wait_for_function("window.plantViewer!==undefined", timeout=240000)
        page.wait_for_timeout(1000)
        page.evaluate(HELPERS)

    def reload(self):
        self.load()

    def state(self, object_id=CHAIR):
        return self.page.evaluate(STATE, object_id)

    def report(self, label, object_id=CHAIR):
        s = self.state(object_id)
        fmt = lambda p: None if p is None else [round(p[0], 2), round(p[2], 2)]
        apart = None
        if s["backend"]:
            apart = round(((s["viewer"][0] - s["backend"][0]) ** 2 + (s["viewer"][2] - s["backend"][2]) ** 2) ** 0.5, 3)
        gap = None if s["gap"] is None else round(s["gap"], 3)
        print(
            f"{label:<34} chair viewer {fmt(s['viewer'])} backend {fmt(s['backend'])} apart {apart} | "
            f"route {s['length']} gap {gap} | queued {s['changes']} posted {s['posted']} | {s['status'][:70]}",
            flush=True,
        )
        return s

    def route_to_fault(self):
        with self.page.expect_response(lambda r: r.url.endswith("/api/route"), timeout=30000):
            self.page.click("#go-fault")
        self.page.wait_for_timeout(300)

    def drag(self, object_id, waypoints, step_ms=16, per_leg=40, hold_ms=250):
        """Select an object, press Move on floor, and drag it through floor points with the mouse."""
        page = self.page
        page.evaluate("(id) => window.__h.v.showInfo(window.__h.byId(id))", object_id)
        page.wait_for_timeout(150)
