                    current[0] + (goal[0] - current[0]) * i / per_leg,
                    current[1] + (goal[1] - current[1]) * i / per_leg,
                )
                page.wait_for_timeout(step_ms)
            current = goal
        page.wait_for_timeout(hold_ms)
        during = self.state(object_id)
        page.mouse.up()
        page.wait_for_timeout(1500)
        return during

    def walk_viewer(self, x, z):
        """Move the viewer the way WASD does, and wait for the route's re-plan."""
        page = self.page
        try:
            with page.expect_response(lambda r: r.url.endswith("/api/route"), timeout=8000):
                page.evaluate("([x, z]) => window.__h.moveViewer(x, z)", [x, z])
        except Exception:
            return False
        page.wait_for_timeout(300)
        return True

    def undo(self):
